CREATE OR REPLACE FUNCTION public.guard_currency_related_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE curr text; BEGIN PERFORM public.lock_tenant_currency(new.tenant_id); SELECT currency_code INTO curr FROM public.tenants WHERE id=new.tenant_id; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown organization'; END IF; IF to_jsonb(new) ? 'currency_code' AND NOT (tg_table_name='financial_failure_events' AND (to_jsonb(new)->>'currency_code') IS NULL) AND (to_jsonb(new)->>'currency_code') IS DISTINCT FROM curr THEN RAISE EXCEPTION 'Financial records must use the organization currency'; END IF; RETURN new; END $$;